  const FIG = [["Ce lion est un vrai foudre de guerre.", "la métaphore"], ["Il est fort comme un lion.", "la comparaison"], ["Le vent hurle dans la nuit.", "la personnification"], ["Je meurs de soif.", "l'hyperbole"], ["Va, je ne te hais point.", "la litote"], ["Il nous a quittés hier soir (il est mort).", "l'euphémisme"], ["Rome, l'unique objet de mon ressentiment ! Rome, à qui vient ton bras d'immoler mon amant !", "l'anaphore"], ["Je vis, je meurs ; je me brûle et me noie.", "l'antithèse"], ["Cette obscure clarté qui tombe des étoiles.", "l'oxymore"], ["Il faut manger pour vivre et non vivre pour manger.", "le chiasme"], ["Va, cours, vole, et nous venge !", "la gradation"], ["Boire un verre.", "la métonymie"], ["La ville lumière (Paris).", "la périphrase"], ["Pour qui sont ces serpents qui sifflent sur vos têtes ?", "l'allitération"], ["Tout m'afflige et me nuit et conspire à me nuire.", "l'assonance"], ["Quel courage ! Il s'est enfui au premier bruit.", "l'ironie"], ["Ô temps, suspends ton vol !", "l'apostrophe"], ["Une voile à l'horizon (un bateau).", "la synecdoque"], ["Monter en haut.", "le pléonasme"], ["Femme nue, femme noire, vêtue de ta couleur qui est vie.", "l'anaphore"]];
