    paire(sid, ch, [["la métaphore", "un rapprochement entre deux réalités sans outil de comparaison"], ["la comparaison", "un rapprochement entre deux réalités avec un outil (comme, tel, pareil à)"], ["la personnification", "le fait de prêter des traits humains à une chose ou à un animal"], ["l'hyperbole", "une exagération pour frapper les esprits"], ["la litote", "dire moins pour faire entendre plus"], ["l'euphémisme", "atténuer une réalité pénible ou choquante"], ["l'anaphore", "la répétition d'un mot en début de vers ou de phrase"], ["l'antithèse", "l'opposition de deux mots ou idées dans une même phrase"], ["l'oxymore", "l'alliance de deux mots de sens contraire, étroitement liés"], ["le chiasme", "la disposition croisée de mots : A B / B A"], ["la gradation", "une suite de termes d'intensité croissante ou décroissante"], ["la métonymie", "désigner une chose par une autre qui lui est liée (le contenant pour le contenu)"], ["la périphrase", "remplacer un mot par une expression qui le décrit"], ["l'allitération", "la répétition d'un même son consonne"], ["l'assonance", "la répétition d'un même son voyelle"]], (f) => `Qu'est-ce que ${f} ?`, (d) => `Quelle figure correspond à : ${d} ?`);
