  oeuvre(TF, "Le roman et les mouvements littéraires", [["Le Père Goriot", "Balzac"], ["Madame Bovary", "Flaubert"], ["Germinal", "Zola"], ["Les Misérables", "Victor Hugo"], ["Le Rouge et le Noir", "Stendhal"], ["L'Étranger", "Albert Camus"], ["Candide", "Voltaire"], ["Les Fleurs du mal", "Baudelaire"], ["Bel-Ami", "Maupassant"], ["La Princesse de Clèves", "Madame de La Fayette"], ["Gargantua", "Rabelais"], ["La Peste", "Albert Camus"]]);
