  paire(TF, "Le roman et les mouvements littéraires", [["le narrateur omniscient", "un narrateur qui sait tout des personnages, même leurs pensées"], ["la focalisation interne", "le récit vu à travers les yeux d'un seul personnage"], ["la focalisation externe", "le récit vu de l'extérieur, comme par une caméra"], ["l'incipit", "le début d'un roman"], ["le schéma narratif", "situation initiale, élément perturbateur, péripéties, dénouement, situation finale"], ["l'analepse (retour en arrière)", "le récit d'un événement antérieur au moment de l'histoire"], ["le roman épistolaire", "un roman écrit sous forme de lettres"], ["le roman d'apprentissage", "un roman qui suit la formation d'un jeune héros"]], (t) => `Que désigne ${t} ?`, (d) => `Quel terme correspond à : ${d} ?`);
  paire(TF, "Le théâtre classique", [["la règle des trois unités", "une seule action, en un seul lieu, en une journée"], ["la bienséance", "ne rien montrer sur scène qui choque le public (mort, violence)"], ["la vraisemblance", "ce qui est montré doit paraître crédible"], ["la catharsis", "la purification des passions du spectateur par la terreur et la pitié"], ["l'exposition", "la première scène qui présente les personnages et la situation"], ["le dénouement", "la fin qui résout le conflit"], ["la tirade", "une longue réplique d'un personnage"], ["le monologue", "un personnage seul en scène qui parle"], ["l'aparté", "une réplique dite pour le public, que les autres personnages sont censés ne pas entendre"], ["la stichomythie", "un échange rapide de répliques courtes, vers à vers"], ["la didascalie", "une indication de mise en scène écrite par l'auteur"], ["le quiproquo", "un malentendu où un personnage est pris pour un autre"], ["le coup de théâtre", "un événement inattendu qui change brusquement l'action"]], (t) => `Que désigne ${t} ?`, (d) => `Quel terme correspond à : ${d} ?`);
  oeuvre(TF, "Le théâtre classique", [["Le Cid", "Corneille"], ["Horace", "Corneille"], ["Phèdre", "Racine"], ["Andromaque", "Racine"], ["Britannicus", "Racine"], ["Tartuffe", "Molière"], ["L'Avare", "Molière"], ["Le Misanthrope", "Molière"], ["Les Femmes savantes", "Molière"], ["Le Bourgeois gentilhomme", "Molière"]]);
  classe(TF, "Le théâtre classique", { "une tragédie": ["Phèdre", "Andromaque", "Britannicus", "Horace"], "une comédie": ["L'Avare", "Tartuffe", "Le Bourgeois gentilhomme", "Les Femmes savantes"] }, (g) => `Laquelle de ces pièces est ${g} ?`, null);
  paire(TF, "Méthodes : dissertation et commentaire", [["l'amorce", "la phrase d'ouverture qui amène le sujet"], ["la problématique", "la question à laquelle le devoir va répondre"], ["l'annonce du plan", "la présentation des grandes parties à la fin de l'introduction"], ["le plan dialectique", "thèse, antithèse, synthèse (ou dépassement)"], ["le plan thématique", "des parties qui étudient chacune un aspect du sujet"], ["la transition", "le passage qui fait le bilan d'une partie et annonce la suivante"], ["l'ouverture", "l'élargissement du sujet à la fin de la conclusion"], ["les axes de lecture", "les grandes idées qui organisent un commentaire de texte"], ["l'argument", "l'idée qui soutient une thèse"], ["l'exemple", "le cas précis, tiré d'une œuvre, qui illustre un argument"], ["la citation", "une phrase du texte reproduite entre guillemets"], ["le résumé de texte", "la contraction du texte au quart environ, avec une marge de 10 %"]], (t) => `En méthode, que désigne ${t} ?`, (d) => `Quel élément de méthode correspond à : ${d} ?`);
  add(TF, "Méthodes : dissertation et commentaire", (r) => { const n = ri(r, 30, 90) * 10, q = n / 4;
    return { q: `Un texte de ${n} mots doit être résumé au quart. Combien de mots au plus (marge de 10 %) ?`, ok: String(Math.round(q * 1.1)), faux: autres(r, [Math.round(q), Math.round(q * 0.9), Math.round(n / 2), Math.round(n / 3)], Math.round(q * 1.1)), e: `Quart : ${n} / 4 = ${q} mots ; marge de 10 % : entre ${Math.round(q * 0.9)} et ${Math.round(q * 1.1)} mots.` }; });
  add(TF, "Méthodes : dissertation et commentaire", (r) => { const parts = ["l'amorce", "la présentation du sujet", "la problématique", "l'annonce du plan"], i = ri(r, 0, 2);
    return { q: `Dans une introduction de dissertation, que vient-il juste après ${parts[i]} ?`, ok: parts[i + 1], faux: autres(r, [...parts, "l'ouverture", "la synthèse"], parts[i + 1]), e: `Ordre : ${parts.join(" → ")}.` }; });

  // =====================================================================================================
